SELECT 1 FROM control.decisions WHERE suit_slug='doctor-suit' AND decision_id LIKE 'DOS-M%-GATE-START' FOR SHARE;
SELECT pg_temp.doctor_assert((SELECT count(*) FROM control.decisions WHERE suit_slug='doctor-suit' AND decision_id LIKE 'DOS-M%-GATE-START' AND status='open')=9,'All nine start gates must remain OPEN');
SELECT pg_temp.doctor_assert(NOT EXISTS(SELECT 1 FROM doctor_import_input i,jsonb_array_elements(i.doc->'all_start_decisions') x LEFT JOIN control.decisions d ON d.suit_slug='doctor-suit' AND d.decision_id=x->>'decision_id' WHERE d.status IS DISTINCT FROM 'open' OR d.metadata->'canonical_decision_contract' IS DISTINCT FROM x),'Start-decision identity/content drift');
SELECT pg_temp.doctor_assert(NOT EXISTS(SELECT 1 FROM control.tasks t WHERE t.suit_slug='doctor-suit' AND NOT EXISTS(SELECT 1 FROM control.task_decisions td JOIN control.decisions d USING(suit_slug,decision_id) WHERE td.task_id=t.task_id AND td.suit_slug='doctor-suit' AND td.decision_id=t.metadata->>'milestone_id'||'-GATE-START' AND td.blocking AND d.status='open')),'Task lacks own real OPEN blocking start gate');
SELECT pg_temp.doctor_assert_stopped();
SELECT pg_temp.doctor_assert(jsonb_build_object('tasks',(SELECT count(*) FROM control.tasks WHERE suit_slug='doctor-suit'),'requirements',(SELECT count(*) FROM control.requirements WHERE suit_slug='doctor-suit'),'decisions',(SELECT count(*) FROM control.decisions WHERE suit_slug='doctor-suit'))=(SELECT doc->'expected_counts' FROM doctor_import_input),'Partial or unexpected Doctor task/requirement/decision counts');
SELECT jsonb_build_object('source_head','7a6dcc2084000b4054010d94a04a85a408282497','milestone',(SELECT doc->>'milestone_id' FROM doctor_import_input),'doctor_tasks',(SELECT count(*) FROM control.tasks WHERE suit_slug='doctor-suit'),'open_start_gates',(SELECT count(*) FROM control.decisions WHERE suit_slug='doctor-suit' AND decision_id LIKE 'DOS-M%-GATE-START' AND status='open'),'ready_doctor_tasks',(SELECT count(*) FROM control.ready_tasks WHERE suit_slug='doctor-suit'),'transaction_end','rollback-only; no committed import claimed') AS validation_receipt;
ROLLBACK;
